<script>
(function(){
  var ids=['x1go-bc','x1go-imgcol','x1go-info'];
  function trigger(){ids.forEach(function(id){var el=document.getElementById(id);if(el)el.classList.add('x1go-vis');});}
  if(document.readyState==='complete'){trigger();}else{window.addEventListener('load',trigger);}
  var mainImg=document.getElementById('x1go-main-img');
  var thumbs=document.querySelectorAll('.x1go-hero__thumb');
  thumbs.forEach(function(thumb){
    thumb.addEventListener('click',function(){
      var src=thumb.getAttribute('data-src');
      if(src&&mainImg){mainImg.style.opacity='0';mainImg.style.transition='opacity .2s ease';setTimeout(function(){mainImg.src=src;mainImg.style.opacity='1';},180);}
      thumbs.forEach(function(t){t.classList.remove('x1go-hero__thumb--active');});
      thumb.classList.add('x1go-hero__thumb--active');
    });
  });
})();
</script>

