  ['x1go-tech-hdr','x1go-tech-plat','x1go-tech-cmp','x1go-tech-feats','x1go-tech-apps-hdr','x1go-tech-apps'].forEach(function(id){var el=document.getElementById(id);if(el)obs.observe(el);});
})();
</script>
